() => {
  const all = document.querySelectorAll('*');
  const results = [];
  for (const el of all) {
    if (el.children.length === 0 && el.textContent && el.textContent.includes('报告模式')) {
      results.push({
        tag: el.tagName,
        text: el.textContent.trim().slice(0, 50),
        className: el.className.toString().slice(0, 80),
        id: el.id
      });
    }
  }
  // also find toggle/switch elements
  const switches = document.querySelectorAll('[role="switch"], input[type="checkbox"]');
  const swInfo = [];
  switches.forEach(s => {
    swInfo.push({
      tag: s.tagName,
      role: s.getAttribute('role'),
      checked: s.checked !== undefined ? s.checked : s.getAttribute('aria-checked'),
      ariaLabel: s.getAttribute('aria-label'),
      nearbyText: s.parentElement ? s.parentElement.textContent.trim().slice(0, 60) : ''
    });
  });
  return { reportModeTexts: results, switches: swInfo };
}

() => {
  // 查找所有按钮，看其文本或 aria-label 是否包含 报告/模板/toggle
  const btns = document.querySelectorAll('button');
  const results = [];
  btns.forEach(b => {
    const t = (b.textContent || '').trim();
    const al = b.getAttribute('aria-label') || '';
    const title = b.getAttribute('title') || '';
    if (t.includes('报告') || al.includes('报告') || title.includes('报告') || t.includes('模式')) {
      results.push({ text: t.slice(0, 60), ariaLabel: al, title, className: b.className.toString().slice(0, 100) });
    }
  });
  return results;
}

