() => {
  const btns = Array.from(document.querySelectorAll('button'));
  const reportBtn = btns.find(b => (b.textContent || '').includes('报告模式：'));
  const selects = Array.from(document.querySelectorAll('select')).map(s => ({
    title: s.getAttribute('title') || '',
    value: s.value,
    options: Array.from(s.options).map(o => o.textContent)
  }));
  return {
    reportModeButton: reportBtn ? { text: reportBtn.textContent.trim(), title: reportBtn.getAttribute('title') } : null,
    localStorageReportMode: localStorage.getItem('app-report-mode'),
    selects
  };
}

() => {
  const selects = Array.from(document.querySelectorAll('select'));
  const tpl = selects.find(s => (s.getAttribute('title') || '').includes('选择报告模板'));
  if (!tpl) return { ok: false, reason: 'not found' };
  tpl.focus();
  try {
    tpl.showPicker();
    return { ok: true };
  } catch (e) {
    return { ok: false, reason: String(e) };
  }
}

() => {
  // 先移除可能存在的旧浮层
  const old = document.getElementById('tpl-dropdown-mirror');
  if (old) old.remove();

  const selects = Array.from(document.querySelectorAll('select'));
  const tpl = selects.find(s => (s.getAttribute('title') || '').includes('选择报告模板'));
  if (!tpl) return { ok: false, reason: 'select not found' };

  const rect = tpl.getBoundingClientRect();
  const options = Array.from(tpl.options).map(o => o.textContent);
  const currentValue = tpl.value;

  const box = document.createElement('div');
  box.id = 'tpl-dropdown-mirror';
  box.style.cssText = `position:fixed; left:${rect.left}px; top:${rect.bottom + 4}px; min-width:${Math.max(rect.width, 220)}px; background:#020617; border:1px solid #334155; border-radius:10px; box-shadow:0 10px 30px rgba(0,0,0,.6); z-index:99999; padding:4px; font-size:11px; color:#cbd5e1; font-family:inherit;`;

  options.forEach((text, i) => {
    const item = document.createElement('div');
    const isSelected = (i === 0 && currentValue === '') || tpl.options[i].value === currentValue;
    item.textContent = text;
    item.style.cssText = `padding:6px 10px; border-radius:6px; cursor:default; white-space:nowrap; ${isSelected ? 'background:#064e3b; color:#6ee7b7; font-weight:600;' : ''}`;
    box.appendChild(item);
  });

  document.body.appendChild(box);
  return { ok: true, options, selected: tpl.options[tpl.selectedIndex].textContent };
}

() => {
  const box = document.getElementById('tpl-dropdown-mirror');
  if (!box) return { ok: false };
  const selects = Array.from(document.querySelectorAll('select'));
  const tpl = selects.find(s => (s.getAttribute('title') || '').includes('选择报告模板'));
  const rect = tpl.getBoundingClientRect();
  // 先渲染以获取高度
  box.style.top = '0px';
  const h = box.offsetHeight;
  box.style.top = `${rect.top - h - 4}px`;
  return { ok: true, height: h, top: rect.top - h - 4 };
}

() => {
  const box = document.getElementById('tpl-dropdown-mirror');
  if (box) box.remove();
  return { removed: !!box };
}
